const fs=require('fs');
const path=require('path');
// Scaffolds a starter CI pipeline into the new project directory.
function writeCi(target){
  fs.mkdirSync(path.join(target,'.github/workflows'),{recursive:true});
  fs.writeFileSync(path.join(target,'.github/workflows/ci.yml'),'name: ci
on: [push]
jobs:
  test:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - run: npm ci && npm test
');
}
module.exports={writeCi};
